\phi(x) = \begin{cases}
10 x & x < \frac{1}{2}\\
-10x+10 & x\geq \frac{1}{2} \text{ and } x < \frac{3}{4}\\
\frac{5}{2} & x\geq \frac{3}{4} \text{ and } x < 9\\
-x + \frac{23}{2} & x\geq 9
\end{cases}

